ce in the batch: True or False]\n    bias: (dim,)\n    activation: either None or \"silu\" or \"swish\" or True\n    pad_slot_id: int\n        if cache_indices is passed, lets the kernel identify padded\n        entries that will not be processed,\n        for example: cache_indices = [pad_slot_id, 1, 20, pad_slot_id]\n        in this case, the kernel will not process entries at\n        indices 0 and 3\n\n    out: same shape as `x`\n    \"\"\"\n    if isinstance(activation, bool) and activation:\n        activation = \"silu\"\n\n    # Record the original dtype of x to preserve it for the output\n    x_dtype = x.dtype\n\n    # Cast x to the same dtype as conv_states to ensure dtype consistency\n    # This is necessary when --mamba-cache-dtype float32 is enabled\n    if conv_states is not None and x.dtype != conv_states.dtype:\n        x = x.to(conv_states.dtype)\n\n    args = None\n    out = torch.empty_like(x)\n    if metadata is not None:\n        cu_seqlen = metadata.cu_seqlen\n        nums_dict = metadata.nums_dict\n        #x = metadata.x\n        args = nums_dict\n        batch_ptr = metadata.batch_ptr\n        token_chunk_offset_ptr = metadata.token_chunk_offset_ptr\n    else:\n        seqlens = np.diff(query_start_loc.to('cpu'))\n        args = seqlens\n        MAX_NUM_PROGRAMS = 1024\n\n        batch_ptr = torch.full(\n            (MAX_NUM_PROGRAMS, ),\n            PAD_SLOT_ID,\n            dtype=torch.int32,\n            device=x.device\n        )  # tracking which seq-idx the Triton program is handling\n        token_chunk_offset_ptr = torch.full(\n            (MAX_NUM_PROGRAMS, ),\n            PAD_SLOT_ID,\n            dtype=torch.int32,\n            device=x.device\n        )  # tracking BLOCK_M-based index in the sequence the Triton program is handling\n\n    is_channel_last = (x.stride(0) == 1) & (x.stride(1) > 1)\n    dim, cu_seqlen = x.shape\n    _, width = weight.shape\n    state_len = width - 1\n    np2_statelen = triton.next_power_of_2(state_len)\n\n    padded_batch = query_start_loc.size(0) - 1\n    stride_x_seq = 0\n    stride_x_dim = x.stride(0)\n    stride_x_token = x.stride(1)\n    stride_w_dim = weight.stride(0)\n    stride_w_width = weight.stride(1)\n    stride_istate_seq = 0\n    stride_istate_dim = 0\n    stride_istate_token = 0\n    num_cache_lines = 0\n    if conv_states is not None:\n        # extensions to support vLLM:\n        # 1. conv_states is used to replaced initial_states\n        # 2. conv_states serve as a cache with num cache lines can be larger than batch size\n        # 3. mapping from sequence x[idx] to a cache line at index as specified via cache_indices[idx]\n        # 4. computation can be skipped if cache_indices[idx] == pad_slot_id\n        num_cache_lines = conv_states.size(0)\n        assert (num_cache_lines == conv_states.shape[0]\n                and dim == conv_states.shape[1]\n                and width - 1 <= conv_states.shape[2])\n        stride_istate_seq = conv_states.stride(0)\n        stride_istate_dim = conv_states.stride(1)\n        stride_istate_token = conv_states.stride(2)\n        assert stride_istate_dim == 1\n    if out.dim() == 2:\n        stride_o_seq = 0\n        stride_o_dim = out.stride(0)\n        stride_o_token = out.stride(1)\n    else:\n        stride_o_seq = out.stride(0)\n        stride_o_dim = out.stride(1)\n        stride_o_token = out.stride(2)\n\n    if validate_data:\n        assert x.dim() == 2\n        assert query_start_loc is not None\n        assert query_start_loc.dim() == 1\n        assert x.stride(0) == 1 or x.stride(1) == 1\n        if bias is not None:\n            assert bias.dim() == 1\n            assert dim == bias.size(0)\n        if cache_indices is not None:\n            assert cache_indices.dim() == 1\n            assert padded_batch == cache_indices.size(0)\n        if has_initial_state is not None:\n            assert has_initial_state.size() == (padded_batch, )\n            assert conv_states is not None, \"ERROR: `has_initial_state` is used, which needs also `conv_states`\"\n        assert weight.stride(1) == 1\n        assert (dim, width) == weight.shape\n        assert is_channel_last, \"Need to run in channel-last layout\"\n\n    if metadata is None:\n\n        def num_program(META, seqlens):\n            tot = 0\n\n            mlist = []\n            offsetlist = []  # type: ignore\n\n            nums = -(-seqlens // META[\"BLOCK_M\"])\n\n            tot = nums.sum().item()\n            mlist = np.repeat(np.arange(len(nums)), nums)\n            for idx, num in enumerate(nums):\n                offsetlist.extend(\n                    range(num)\n                )  # chunk-idx if a sequence is split into multiple chunks\n\n            if META[\"batch_ptr\"].nelement() < len(mlist):\n                newlen = len(mlist) + 1\n                META[\"batch_ptr\"].resize_(newlen).fill_(PAD_SLOT_ID)\n                META[\"token_chunk_offset_ptr\"].resize_(newlen).fill_(\n                    PAD_SLOT_ID)\n\n            if META[\"batch_ptr\"].nelement() >= len(mlist):\n                META[\"batch_ptr\"][0:len(mlist)].copy_(\n                    torch.from_numpy(np.array(mlist)))\n                META[\"token_chunk_offset_ptr\"][0:len(mlist)].copy_(\n                    torch.from_numpy(np.array(offsetlist)))\n\n            META[\"batch_ptr\"] = META[\"batch_ptr\"].to(META[\"x_ptr\"].device)\n            META[\"token_chunk_offset_ptr\"] = META[\"token_chunk_offset_ptr\"].to(\n                META[\"x_ptr\"].device)\n            return tot\n    else:\n\n        def num_program(META, nums_dict):\n            tot = nums_dict[META[\"BLOCK_M\"]]['tot']\n\n            mlist = nums_dict[META[\"BLOCK_M\"]]['mlist']\n            mlist_len = nums_dict[META[\"BLOCK_M\"]]['mlist_len']\n\n            offsetlist = nums_dict[META[\"BLOCK_M\"]]['offsetlist']\n\n            if nums_dict[META[\"BLOCK_M\"]][\"batch_ptr\"] is not None:\n                META[\"batch_ptr\"] = nums_dict[META[\"BLOCK_M\"]][\"batch_ptr\"]\n                META[\"token_chunk_offset_ptr\"] = nums_dict[\n                    META[\"BLOCK_M\"]][\"token_chunk_offset_ptr\"]\n            else:\n                if META[\"batch_ptr\"].nelement() < mlist_len:\n                    newlen = mlist_len + 1\n                    META[\"batch_ptr\"].resize_(newlen).fill_(PAD_SLOT_ID)\n                    META[\"token_chunk_offset_ptr\"].resize_(newlen).fill_(\n                        PAD_SLOT_ID)\n\n                if META[\"batch_ptr\"].nelement() >= mlist_len:\n                    META[\"batch_ptr\"][0:mlist_len].copy_(mlist)\n                    META[\"token_chunk_offset_ptr\"][0:mlist_len].copy_(\n                        offsetlist)\n            return tot\n\n    def grid(META):\n        return (\n            num_program(META, args),\n            triton.cdiv(dim, META[\"BLOCK_N\"]),\n        )\n\n    if batch_ptr.device != x.device:\n        batch_ptr = batch_ptr.to(x.device)\n        token_chunk_offset_ptr = token_chunk_offset_ptr.to(x.device)\n\n    _causal_conv1d_fwd_kernel[grid](\n        # Pointers to matrices\n        x,\n        weight,\n        bias,\n        conv_states,\n        cache_indices,\n        has_initial_state,\n        query_start_loc,\n        batch_ptr,\n        token_chunk_offset_ptr,\n        out,\n        # Matrix dimensions\n        padded_batch,\n        dim,\n        cu_seqlen,\n        num_cache_lines,\n        # stride\n        stride_x_seq,\n        stride_x_dim,\n        stride_x_token,\n        stride_w_dim,\n        stride_w_width,\n        stride_istate_seq,\n        stride_istate_dim,\n        stride_istate_token,\n        stride_o_seq,\n        stride_o_dim,\n        stride_o_token,\n        # others\n        pad_slot_id,\n        # META\n        HAS_BIAS=bias is not None,\n        KERNEL_WIDTH=width,\n        SILU_ACTIVATION=activation in [\"silu\", \"swish\"],\n        HAS_INITIAL_STATES=has_initial_state is not None,\n        HAS_CACHE=conv_states is not None,\n        IS_CONTINUOUS_BATCHING=cache_indices is not None,\n        USE_PAD_SLOT=pad_slot_id is not None,\n        NP2_STATELEN=np2_statelen,\n        #launch_cooperative_grid=True\n        BLOCK_M=8,\n        BLOCK_N=256,\n        num_stages=2,\n    )\n    # Cast the output back to the original input dtype\n    if out.dtype != x_dtype:\n        out = out.to(x_dtype)\n    return out",
        "causal_conv1d_update": "def causal_conv1d_update(\n    x: torch.Tensor,\n    conv_state: torch.Tensor,\n    weight: torch.Tensor,\n    bias: Optional[torch.Tensor] = None,\n    activation: Union[bool, str, None] = None,\n    cache_seqlens: Optional[torch.Tensor] = None,\n    conv_state_indices: Optional[torch.Tensor] = None,\n    num_accepted_tokens: Optional[torch.Tensor] = None,\n    query_start_loc: Optional[torch.Tensor] = None,\n    max_query_len: int = -1,\n    pad_slot_id: int = PAD_SLOT_ID,\n    metadata=None,\n    validate_data=False,\n):\n    \"\"\"\n    x: (batch, dim) or (batch, dim, seqlen) or (num_tokens, dim)\n        [shape=2: single token prediction]\n        [shape=3: single or multiple tokens prediction]\n        [shape=2 with num_tokens: continuous batching, where num_tokens is the\n                                  total tokens of all sequences in that batch]\n    conv_state: (..., dim, state_len), where state_len >= width - 1\n    weight: (dim, width)\n    bias: (dim,)\n    cache_seqlens: (batch,), dtype int32.\n        If not None, the conv_state is treated as a circular buffer.\n        The conv_state will be updated by copying x to the conv_state\n        starting at the index\n        @cache_seqlens % state_len.\n    conv_state_indices: (batch,), dtype int32\n        If not None, the conv_state is a larger tensor along the batch dim,\n        and we are selecting the batch coords specified by conv_state_indices.\n        Useful for a continuous batching scenario.\n    num_accepted_tokens: (batch,), dtype int32\n        If not None, it indicates the number of accepted tokens for each\n        sequence in the batch.\n        This is used in speculative decoding, where the conv_state is updated\n        in a sliding window manner.\n    query_start_loc: (batch + 1,) int32\n        If not None, the inputs is given in a varlen fashion and this indicates\n        the starting index of each sequence in the batch.\n    max_query_len: int\n        If query_start_loc is not None, this indicates the maximum query\n        length in the batch.\n    pad_slot_id: int\n            if cache_indices is passed, lets the kernel identify padded\n            entries that will not be processed,\n            for example: cache_indices = [pad_slot_id, 1 ,20 ,pad_slot_id]\n            in this case, the kernel will not process entries at\n            indices 0 and 3\n    out: (batch, dim) or (batch, dim, seqlen) or (num_tokens, dim), same shape as `x`\n    \"\"\"\n    if validate_data:\n        assert cache_seqlens is None  # not implemented yet - ok for vLLM\n        assert pad_slot_id is not None\n        assert x.stride(1) == 1\n    if isinstance(activation, bool):\n        activation = \"silu\" if activation is True else None\n    elif activation is not None:\n        assert activation in [\"silu\", \"swish\"]\n    unsqueeze = query_start_loc is None and x.dim() == 2\n    if unsqueeze:\n        # make it (batch, dim, seqlen) with seqlen == 1\n        x = x.unsqueeze(-1)\n    if query_start_loc is None:\n        batch, dim, seqlen = x.shape\n    else:\n        assert conv_state_indices is not None\n        batch = conv_state_indices.size(0)\n        dim = x.size(1)\n        seqlen = max_query_len\n    _, width = weight.shape\n    # conv_state: (..., dim, state_len), where state_len >= width - 1\n    num_cache_lines, _, state_len = conv_state.size()\n\n    if validate_data:\n        assert dim == weight.size(0)\n        assert conv_state.stride(\n            -2\n        ) == 1, f\"ERROR: expect contiguous along feat-dim of conv_state (currently stride={conv_state.stride()})\"\n        assert state_len >= width - 1\n        # when above happens, we don't shift-left to keep any records in conv_state\n        assert dim == conv_state.size(1)\n        if conv_state_indices is None:\n            assert conv_state.size(0) >= batch\n        else:\n            assert (batch, ) == conv_state_indices.shape\n\n        assert num_cache_lines >= batch\n        assert weight.stride(1) == 1  # Need this\n        assert cache_seqlens is None  # not needed for vLLM - circular buffer\n\n    # Record the original dtype of x to preserve it for the output\n    x_dtype = x.dtype\n\n    # Cast x to the same dtype as conv_state to ensure dtype consistency\n    # This is necessary when --mamba-cache-dtype float32 is enabled\n    if x.dtype != conv_state.dtype:\n        x = x.to(conv_state.dtype)\n\n    # adopt the strategy in vLLM that overwrite on 'x' directly, rather than creating a new tensor 'o'\n    out = x\n    stride_w_dim, stride_w_width = weight.stride()\n\n    if query_start_loc is None:\n        # X (batch, dim, seqlen)\n        stride_x_seq, stride_x_dim, stride_x_token = x.stride()\n        stride_o_seq, stride_o_dim, stride_o_token = out.stride()\n    else:\n        # X (dim, cu_seqlen)\n        stride_x_token, stride_x_dim = x.stride()\n        stride_x_seq = 0\n        stride_o_token, stride_o_dim = out.stride()\n        stride_o_seq = 0\n\n    stride_istate_seq, stride_istate_dim, stride_istate_token = conv_state.stride(\n    )\n    stride_state_indices = conv_state_indices.stride(\n        0) if conv_state_indices is not None else 0\n    if num_accepted_tokens is not None:\n        state_len = width - 1 + (seqlen - 1)  # effective state_len needed\n    else:\n        state_len = width - 1\n    np2_statelen = triton.next_power_of_2(state_len)\n\n    def grid(META):\n        return (\n            batch,\n            triton.cdiv(dim, META[\"BLOCK_N\"]),\n        )\n\n    _causal_conv1d_update_kernel[grid](\n        # Pointers to matrices\n        x,\n        weight,\n        bias,\n        conv_state,\n        cache_seqlens,\n        conv_state_indices,\n        num_accepted_tokens,\n        query_start_loc,\n        out,\n        # Matrix dimensions\n        batch,\n        dim,\n        seqlen,\n        state_len,\n        num_cache_lines,\n        # stride\n        stride_x_seq,\n        stride_x_dim,\n        stride_x_token,\n        stride_w_dim,\n        stride_w_width,\n        stride_istate_seq,\n        stride_istate_dim,\n        stride_istate_token,\n        stride_state_indices,\n        stride_o_seq,\n        stride_o_dim,\n        stride_o_token,\n        # others\n        pad_slot_id,\n        # META\n        HAS_BIAS=bias is not None,\n        KERNEL_WIDTH=width,\n        SILU_ACTIVATION=activation in [\"silu\", \"swish\"],\n        IS_VARLEN=query_start_loc is not None,\n        IS_CONTINUOUS_BATCHING=conv_state_indices is not None,\n        IS_SPEC_DECODING=num_accepted_tokens is not None,\n        NP2_STATELEN=np2_statelen,\n        USE_PAD_SLOT=pad_slot_id is not None,\n        BLOCK_N=256,\n    )\n    if unsqueeze:\n        out = out.squeeze(-1)\n    # Cast the output back to the original input dtype\n    if out.dtype != x_dtype:\n        out = out.to(x_dtype)\n    return out"
    }
}
JSONEOF"}

